<script setup>
import { computed,ref } from 'vue';
import { INV_STATE,invClass,money,num,fdate } from '../../lib/client-info';
import ClientInvoice from './ClientInvoice.vue';
import ClientSections from './ClientSections.vue';
const props=defineProps({bundle:Object,metrics:Object,payments:Array,busy:Boolean,error:String});
defineEmits(['retry']);
const filter=ref('all'),filters=['all','unpaid','partial','overdue','paid'];
const filtered=computed(()=>props.bundle.invoices.filter(row=>filter.value==='all'||invClass(row)===filter.value||(filter.value==='unpaid'&&invClass(row)==='overdue')));
const amount=row=>num(row.base_received_amount)||num(row.received_amount)||num(row.paid_amount);
const modes=computed(()=>{const map=new Map();for(const row of props.payments){const key=row.mode_of_payment||'Other';map.set(key,(map.get(key)||0)+amount(row));}return[...map].sort((a,b)=>b[1]-a[1]);});
const sections=computed(()=>[{id:'summary',icon:'💰',title:'Dues summary',tone:props.metrics.due.overdue?'neg':props.metrics.due.pending?'warn':'ok',badge:money(props.metrics.due.pending),wide:true},{id:'invoices',icon:'🧾',title:'All invoices',badge:props.bundle.invoices.length,wide:true},{id:'payments',icon:'💳',title:'Payments received',badge:props.payments.length,wide:true}]);
</script>
<template><ClientSections name="billing" :sections="sections"><template #summary><div class="c3-grid c3-g5"><div class="c3-money-hero" :class="metrics.due.overdue?'tone-neg':metrics.due.pending?'tone-warn':'tone-ok'"><small>Due amount</small><b>{{ money(metrics.due.pending) }}</b><span>{{ metrics.due.withDues?metrics.due.withDues+' invoices with balance':'All settled' }}</span></div><div v-for="[label,value] in [['Overdue amount',money(metrics.due.overdueAmt)],['Next due date',metrics.due.next?fdate(metrics.due.next)+' — '+money(metrics.due.nextAmt):'—'],['Total billed',money(metrics.billed)],['Paid',money(metrics.paid)]]" :key="label" class="c3-kv"><small>{{ label }}</small><b>{{ value }}</b></div></div></template><template #invoices><div class="c3-filters"><button v-for="value in filters" :key="value" type="button" class="c3-fbtn" :class="{'is-on':filter===value}" @click="filter=value">{{ value==='all'?'All':INV_STATE[value][1] }} ({{ value==='all'?bundle.invoices.length:bundle.invoices.filter(row=>invClass(row)===value).length }})</button></div><div class="c3-inv-grid-list"><ClientInvoice v-for="invoice in filtered" :key="invoice.name" :invoice="invoice" /><div v-if="!filtered.length" class="c3-empty-sm">No invoices.</div></div></template><template #payments><p v-if="busy" role="status">Loading payment entries…</p><p v-else-if="error" role="alert">{{ error }} <button @click="$emit('retry')">Retry</button></p><template v-else><div class="c3-bars"><div v-for="[name,value] in modes" :key="name" class="c3-bar"><span class="c3-bar-l">{{ name }}</span><span class="c3-bar-t"><i :style="{width:value/(modes[0]?.[1]||1)*100+'%'}"></i></span><b>{{ money(value) }}</b></div></div><div v-if="payments.length" class="c3-table-wrap"><table class="c3-mini-table"><thead><tr><th>Date</th><th>Receipt</th><th>Mode</th><th>Branch</th><th class="t-r">Amount</th></tr></thead><tbody><tr v-for="row in payments" :key="row.name"><td>{{ fdate(row.posting_date) }}</td><td>{{ row.name }}</td><td>{{ row.mode_of_payment||'—' }}</td><td>{{ row.branch||'—' }}</td><td class="t-r tone-ok">{{ money(amount(row)) }}</td></tr></tbody></table></div><div v-else class="c3-empty-sm">No payment entries linked to this client's customer record.</div></template></template></ClientSections></template>
